/* Version 2 — research powers join Battle Royale fights (owner decision 2026-11-20: option A, on by
 * default in V2). docs/option-c/RESEARCH_POWERS.md explains the rules.
 *
 * A character with no Version 1 combat profile gets one signature move from its V2 research record
 * (data/option-c/research-moves-data.js, generated by tools/build-research-moves.cjs):
 *  - the power type, guards and weaknesses come from the record;
 *  - the move's name is the record's own technique;
 *  - its strength is ONE fixed standard for every research move (tier 2, 17% pierce, every third
 *    round), because the research deliberately records no power level. Tier 2 never triggers the
 *    tier-4+ ward, damage floor or Apex/Empowered rules, so no character is promoted by research.
 * A Version 1 profile (core or reviewed form) always wins: this module is only asked when the V1
 * lookup returned nothing. Without these two files the fight engine behaves exactly as in V1.
 *
 * The switch: on by default; setEnabled(false) turns research moves off (the page wires it to
 * ?researchPowers=0, remembered per device, and Head-to-Head rooms carry the host's setting so both
 * players replay the same fight).
 */
(function (root) {
  'use strict';
  const isNode = typeof module !== 'undefined' && !!module.exports && typeof require === 'function';
  const STRENGTH = Object.freeze({ tier: 2, pierce: 0.17, cooldown: 3 });
  const LIMIT = 'Research move (Version 2): its power type comes from this character\'s research record. It hits at the standard research strength because the research records no power level.';
  let enabled = true;
  let index = null;

  function data() {
    if (root && root.DA_RESEARCH_MOVES_DATA) return root.DA_RESEARCH_MOVES_DATA;
    return isNode ? require('./research-moves-data.js') : null;
  }
  function lookup() {
    if (index) return index;
    index = Object.create(null);
    const d = data();
    for (const [id, move, domain, guard, weakTo, source, continuity] of (d && d.rows) || []) {
      index[id] = Object.freeze({ move, domain, guard: Object.freeze(guard.slice()), weakTo: Object.freeze(weakTo.slice()), source, continuity });
    }
    return index;
  }
  /* Research identity of a game candidate: "pool:Name", or "pool:Base|Form" for a form. */
  function researchIdOf(c) {
    if (!c || !c.pool || !c.n) return '';
    return c.variantBase ? c.pool + ':' + c.variantBase + '|' + c.n : c.pool + ':' + c.n;
  }
  /* A fresh ability object in the shape the fight engine reads, or null. Never mutates `c`. */
  function researchMoveOf(c) {
    if (!enabled || !c) return null;
    // A reviewed form carries its own V1 kit; research never replaces it.
    if (c.variantAbilities && Array.isArray(c.variantAbilities.domains) && c.variantAbilities.domains.length) return null;
    const m = lookup()[researchIdOf(c)];
    if (!m) return null;
    return {
      move: m.move, domain: m.domain, tier: STRENGTH.tier, pierce: STRENGTH.pierce,
      guard: m.guard.slice(), weakTo: m.weakTo.slice(), cooldown: STRENGTH.cooldown,
      wearStart: 0, wearRate: 0, source: m.source, origin: 'research', limit: LIMIT, continuity: m.continuity,
    };
  }
  /* Run fn with the switch temporarily set (used by Head-to-Head), restoring it afterwards. */
  function withEnabled(on, fn) {
    const before = enabled;
    enabled = !!on;
    try { return fn(); } finally { enabled = before; }
  }

  const api = {
    version: 'research-moves-v1', STRENGTH, LIMIT,
    enabled: () => enabled, setEnabled: (on) => { enabled = !!on; }, withEnabled,
    researchIdOf, researchMoveOf, count: () => Object.keys(lookup()).length,
  };
  if (root) root.DA_RESEARCH_MOVES = api;
  if (isNode) module.exports = api;
})(typeof window !== 'undefined' ? window : typeof globalThis !== 'undefined' ? globalThis : null);
